<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import QRCode from 'qrcode';
const props=defineProps<{registrationUrl:string;paymentUrl:string}>();
const registrationQr=ref<HTMLCanvasElement|null>(null),paymentQr=ref<HTMLCanvasElement|null>(null),copied=ref('');
async function render(){if(registrationQr.value)await QRCode.toCanvas(registrationQr.value,props.registrationUrl,{width:320,margin:2,errorCorrectionLevel:'H'});if(paymentQr.value)await QRCode.toCanvas(paymentQr.value,props.paymentUrl,{width:320,margin:2,errorCorrectionLevel:'H'});}
onMounted(()=>void render());watch(()=>[props.registrationUrl,props.paymentUrl],()=>void render());
async function copy(label:string,url:string){try{await navigator.clipboard.writeText(url);}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();document.execCommand('copy');input.remove();}copied.value=label;window.setTimeout(()=>{if(copied.value===label)copied.value='';},2200);}
function download(canvas:HTMLCanvasElement|null,name:string){if(!canvas)return;const link=document.createElement('a');link.download=name;link.href=canvas.toDataURL('image/png');link.click();}
</script>
<template><section class="space-y-5"><header><h3 class="text-xl font-semibold">Hostel links</h3><p class="text-sm text-ink-muted">Copy a link to share it, or download its QR code as an image.</p></header><div class="grid gap-4 lg:grid-cols-2"><article v-for="item in [{key:'registration',title:'Tenant registration',description:'Applicants enter their details and agree to the accommodation terms. Management reviews applications in Tenants.',url:registrationUrl,canvas:registrationQr,file:'hostel-registration-qr.png'},{key:'rent',title:'Rent payment',description:'Tenants open the payment page, enter their phone number, and view their rent balance and payment options.',url:paymentUrl,canvas:paymentQr,file:'hostel-rent-payment-qr.png'}]" :key="item.key" class="panel flex flex-col items-center gap-3 text-center"><h4 class="text-lg font-semibold">{{item.title}}</h4><p class="text-sm text-ink-muted">{{item.description}}</p><canvas :ref="element=>{if(item.key==='registration')registrationQr=element as HTMLCanvasElement;else paymentQr=element as HTMLCanvasElement}" class="h-64 w-64 rounded bg-white p-2" :aria-label="`${item.title} QR code`" /><code class="max-w-full break-all text-xs">{{item.url}}</code><div class="flex flex-wrap justify-center gap-2"><button type="button" class="btn-secondary" @click="copy(item.key,item.url)">{{copied===item.key?'Copied!':'Copy link'}}</button><button type="button" class="btn" @click="download(item.canvas,item.file)">Download QR code</button></div></article></div></section></template>
